-- Versioned course content migration: seed the 100-module catalogue and Module 01. Only Module 01 is published in this release.
insert into public.course_modules (module_number,course_id,stage_number,title,objective,focus,expected_evidence,learning_tier,content_status,published_at)
select x.module_number,c.id,x.stage_number,x.title,x.objective,x.focus,x.expected_evidence,x.learning_tier,x.content_status,case when x.module_number=1 then now() else null end
from public.courses c cross join (values
  (1 , 1, 'Separate the story from the task', 'Identify the exact outcome requested without confusing background details with the task or its possible implementation.', 'Story versus task; input; action; output', 'A one-sentence task statement that preserves the requested outcome.', 'foundation', 'published', null),
  (2 , 1, 'Express a task as input, rule and output', 'Describe a problem as the information received, the transformation required and the result expected.', 'Input contract; transformation; output contract', 'A complete input–rule–output contract.', 'foundation', 'planned', null),
  (3 , 1, 'Extract constraints and limits', 'Find size, range, uniqueness, ordering and resource restrictions that change which solutions are valid.', 'Bounds; uniqueness; ordering; capacity; limits', 'A constraint sheet that distinguishes explicit limits from assumptions.', 'foundation', 'planned', null),
  (4 , 1, 'Separate facts, assumptions and unknowns', 'Distinguish what the problem guarantees from what a solver is tempted to assume, and identify what must be clarified.', 'Facts; assumptions; ambiguity; clarification', 'A list of confirmed facts, open questions and safe assumptions.', 'foundation', 'planned', null),
  (5 , 1, 'Use examples and counterexamples', 'Create examples that confirm the interpretation and counterexamples that expose an incomplete or incorrect reading.', 'Normal cases; counterexamples; expected outcomes', 'A small example set with independently reasoned expected results.', 'foundation', 'planned', null),
  (6 , 1, 'Discover edge cases before solving', 'Identify empty, minimal, maximal, repeated, missing and unusual inputs relevant to a task.', 'Boundary cases; duplicates; missing values; extremes', 'A ranked edge-case list with a reason each case matters.', 'foundation', 'planned', null),
  (7 , 1, 'Write observable acceptance criteria', 'Convert a vague request into conditions that a proposed result must satisfy to be considered correct.', 'Acceptance criteria; observable behaviour; scope', 'Testable acceptance criteria that can be checked without seeing the implementation.', 'foundation', 'planned', null),
  (8 , 1, 'Decompose a task into subproblems', 'Break a multi-part request into smaller outcomes that can be solved and checked independently.', 'Decomposition; subgoals; responsibility boundaries', 'A dependency-aware breakdown of a larger task.', 'building', 'planned', null),
  (9 , 1, 'Map dependencies between subproblems', 'Determine which outputs are needed before other steps can begin and identify independent work.', 'Dependencies; ordering; independent steps', 'A valid execution order with dependencies explained.', 'building', 'planned', null),
  (10 , 1, 'Turn an unclear request into a precise brief', 'Resolve a realistic, imperfect problem statement into a bounded task with inputs, outputs, constraints and acceptance criteria.', 'Synthesis; scope; specification; clarification', 'A complete problem brief and a justified list of unresolved questions.', 'synthesis', 'planned', null),
  (11 , 2, 'Identify entities and their attributes', 'Extract the objects a problem talks about and the information that describes each one.', 'Entities; attributes; identity; records', 'An entity model that distinguishes identity from descriptive fields.', 'foundation', 'planned', null),
  (12 , 2, 'Distinguish single values from collections', 'Recognise whether a task needs one value, an ordered collection, a group of unique values or keyed records.', 'Scalar values; collections; records', 'A suitable first-pass data representation for several scenarios.', 'foundation', 'planned', null),
  (13 , 2, 'Choose between a sequence and a set', 'Decide whether order and duplicates are meaningful or whether only membership and uniqueness matter.', 'Order; duplicates; membership; uniqueness', 'A representation choice justified by required operations.', 'foundation', 'planned', null),
  (14 , 2, 'Model direct lookup with key–value records', 'Represent information that must be found quickly by a stable identifier or key.', 'Keys; values; lookup; mapping', 'A key–value model with a clear uniqueness rule.', 'building', 'planned', null),
  (15 , 2, 'Model last-in and first-in workflows', 'Recognise when a stack-like or queue-like process matches the order in which work must be handled.', 'LIFO; FIFO; push/pop; enqueue/dequeue concepts', 'A correct workflow model and a trace of its state changes.', 'building', 'planned', null),
  (16 , 2, 'Represent state and state transitions', 'Describe how an object or process changes after an event, while identifying valid and invalid states.', 'State; event; transition; invariant', 'A state-transition model with allowed transitions identified.', 'building', 'planned', null),
  (17 , 2, 'Represent relationships as a network', 'Model entities connected by relationships when a problem concerns reachability, routes or dependencies.', 'Nodes; edges; direction; weights', 'A relationship model with correctly identified nodes and edges.', 'building', 'planned', null),
  (18 , 2, 'Trace information with tables and diagrams', 'Use a state table, decision table or simple diagram to make a multi-step process visible and checkable.', 'Trace tables; decision tables; state diagrams', 'A complete trace that another person can follow.', 'building', 'planned', null),
  (19 , 2, 'Choose a representation from required operations', 'Select a data model by asking what must be looked up, updated, ordered, counted or traversed.', 'Operation-first modelling; trade-offs; representation', 'A reasoned model choice based on the dominant operations.', 'applied', 'planned', null),
  (20 , 2, 'Model a practical domain', 'Translate a small business workflow into entities, relationships, state and operations without relying on a programming language.', 'Domain modelling; entities; relationships; state', 'A coherent model of a realistic workflow.', 'synthesis', 'planned', null),
  (21 , 3, 'Write steps in an unambiguous order', 'Describe a deterministic procedure where each step has a clear purpose and no hidden interpretation.', 'Sequence; precision; preconditions', 'An ordered procedure that produces the intended result on a sample.', 'foundation', 'planned', null),
  (22 , 3, 'Use conditions to make decisions', 'Translate a requirement into a condition and determine which outcome follows when it is true or false.', 'Boolean conditions; decision branches', 'A correct decision rule for each case.', 'foundation', 'planned', null),
  (23 , 3, 'Combine conditions without logic errors', 'Evaluate compound conditions and identify how AND, OR and NOT affect the result.', 'Compound logic; truth tables; short-circuit intuition', 'A complete truth table and correct interpretation of a compound rule.', 'building', 'planned', null),
  (24 , 3, 'Count, accumulate and maintain a running result', 'Distinguish a counter from a running total and update each correctly as records are processed.', 'Counters; accumulators; running state', 'A correct state trace for a count or aggregate.', 'building', 'planned', null),
  (25 , 3, 'Compare values and maintain a best-so-far result', 'Design reasoning for minimum, maximum and selection tasks, including ties and empty input conditions.', 'Comparison; min/max; initialisation; ties', 'A correct comparison strategy with boundary behaviour stated.', 'building', 'planned', null),
  (26 , 3, 'Build multi-branch classification rules', 'Translate several categories and thresholds into mutually clear decision rules, including boundary values.', 'Decision trees; ranges; precedence; boundary ownership', 'A complete decision table with no gaps or overlapping rules.', 'building', 'planned', null),
  (27 , 3, 'Use preconditions, postconditions and invariants', 'State what must be true before a procedure, what it guarantees after, and what remains true during it.', 'Preconditions; postconditions; invariants', 'A concise correctness contract for a procedure.', 'applied', 'planned', null),
  (28 , 3, 'Respect operation order and side effects', 'Recognise when changing the order of steps changes the outcome and identify operations that mutate shared state.', 'Dependencies; sequencing; side effects', 'A safe operation order with side effects called out.', 'applied', 'planned', null),
  (29 , 3, 'Distinguish local choices from global goals', 'Recognise when a locally attractive decision can block a better overall outcome and when a greedy choice is justified.', 'Greedy choice; look-ahead; local versus global', 'A reasoned decision about whether a local-choice strategy is safe.', 'applied', 'planned', null),
  (30 , 3, 'Construct a complete decision workflow', 'Combine conditions, counters, comparisons and invariants to solve a deterministic multi-step task.', 'Logic synthesis; state; decision workflow', 'A traceable procedure with correct results across varied cases.', 'synthesis', 'planned', null),
  (31 , 4, 'Trace repeated actions as changing state', 'Track how each repetition changes values and identify the exact state after a specified number of steps.', 'Iteration; state tables; repeated updates', 'A correct step-by-step trace without executing code.', 'foundation', 'planned', null),
  (32 , 4, 'Determine when repetition should stop', 'Define a termination condition and recognise procedures that stop too early, too late or never.', 'Termination; loop conditions; progress', 'A valid stop condition and an explanation of why progress reaches it.', 'building', 'planned', null),
  (33 , 4, 'Prevent off-by-one boundary errors', 'Reason precisely about inclusive and exclusive endpoints, first and last positions and counts of items.', 'Index boundaries; inclusive/exclusive ranges', 'Correct start, stop and count decisions on boundary examples.', 'building', 'planned', null),
  (34 , 4, 'Reason about nested repetition', 'Count how many operations occur when one repeated process is placed inside another.', 'Nested repetition; iteration counts; growth intuition', 'A correct operation count for nested patterns.', 'building', 'planned', null),
  (35 , 4, 'Scan from both ends with two pointers', 'Recognise problems where two moving positions can replace repeated rescanning.', 'Two pointers; opposing and same-direction scans', 'A pointer-movement plan with a clear stopping condition.', 'applied', 'planned', null),
  (36 , 4, 'Process contiguous ranges with a sliding window', 'Maintain a summary over a moving contiguous range without rebuilding it from scratch each time.', 'Sliding window; fixed and variable windows', 'A window-update trace and a justified validity condition.', 'applied', 'planned', null),
  (37 , 4, 'Use prefix summaries for repeated range questions', 'Precompute cumulative information so multiple range queries can be answered efficiently.', 'Prefix sums; cumulative summaries; range queries', 'A correct prefix model and range-result derivation.', 'applied', 'planned', null),
