  (39 , 4, 'Reason about intervals and overlapping time windows', 'Compare, sort and combine ranges when appointments, events or time periods overlap.', 'Intervals; endpoints; overlap; adjacency', 'A correct interval classification or merge plan.', 'applied', 'planned', null),
  (40 , 4, 'Select a sequence pattern for an unfamiliar task', 'Choose between a direct scan, two pointers, a window, prefix summary or frequency model based on the task structure.', 'Pattern recognition; sequence synthesis', 'A pattern choice supported by the input structure and required output.', 'synthesis', 'planned', null),
  (41 , 5, 'Use lists and arrays for ordered data', 'Reason about position, traversal, insertion, deletion and repeated access in an ordered collection.', 'Index; order; traversal; shifts', 'A correct operation plan for an ordered collection.', 'foundation', 'planned', null),
  (42 , 5, 'Use maps for direct lookup', 'Choose a key-based mapping when a problem repeatedly asks for information by identifier.', 'Key lookup; update; missing keys', 'A map-based solution outline and its lookup/update behaviour.', 'building', 'planned', null),
  (43 , 5, 'Use sets for uniqueness and membership', 'Remove duplicate representation from the reasoning and answer membership questions without preserving order.', 'Set membership; uniqueness; union/intersection intuition', 'A correct set operation plan with order limitations stated.', 'building', 'planned', null),
  (44 , 5, 'Use a stack for unresolved work', 'Model nested or most-recent-first tasks using a last-in-first-out structure.', 'Stack; push/pop; matching; undo', 'A stack trace that preserves the correct processing order.', 'building', 'planned', null),
  (45 , 5, 'Use a queue for arrival-order processing', 'Model first-in-first-out work such as service desks, task buffers and breadth-first exploration.', 'Queue; enqueue/dequeue; fairness; processing order', 'A queue model and a correct sequence of processed items.', 'building', 'planned', null),
  (46 , 5, 'Understand linked records and references', 'Reason about nodes connected by references and the consequences of inserting, removing or losing a link.', 'Nodes; links; references; head/tail', 'A correct linked-structure update sequence.', 'applied', 'planned', null),
  (47 , 5, 'Prioritise work with a priority queue', 'Choose a priority-based structure when the next item is selected by urgency or rank rather than arrival time.', 'Priority; heap intuition; repeated best-item retrieval', 'A priority-processing plan with tie and update behaviour considered.', 'applied', 'planned', null),
  (48 , 5, 'Represent hierarchy with trees', 'Model parent-child relationships and reason about root, leaves, depth and traversal requirements.', 'Tree; root; child; leaf; depth', 'A tree model and a valid traversal plan.', 'applied', 'planned', null),
  (49 , 5, 'Combine structures to support different operations', 'Use one structure for ordered output and another for fast lookup or counting when a task needs both.', 'Composite representation; index; sequence; lookup', 'A composite model that supports all required operations.', 'applied', 'planned', null),
  (50 , 5, 'Choose a data structure from an operation profile', 'Compare realistic operation frequency, ordering needs and update patterns before selecting a representation.', 'Structure selection; workload; trade-offs', 'A defensible structure choice for an unfamiliar scenario.', 'synthesis', 'planned', null),
