  (52 , 6, 'Use binary search only when its preconditions hold', 'Recognise the sorted or monotonic condition required for repeatedly narrowing a search range.', 'Binary search; sortedness; monotonic predicate', 'A valid range-narrowing trace with its precondition stated.', 'building', 'planned', null),
  (53 , 6, 'Use sorting to expose structure', 'Choose sorting when ordered neighbours, ranked output or a later scan makes the task simpler.', 'Sorting; ordering; preprocessing', 'A reasoned decision to sort or avoid sorting.', 'building', 'planned', null),
