  (55 , 6, 'Find the top items without repeatedly sorting everything', 'Choose an appropriate strategy for selecting a small number of highest-ranked items from a larger collection.', 'Top-k; partial selection; heap intuition', 'A selection strategy justified by k and input size.', 'applied', 'planned', null),
  (56 , 6, 'Filter, partition and group records', 'Separate records by predicates and organise them by categories without losing the intended relationship to each record.', 'Filtering; partitioning; grouping', 'A correct grouping plan with all records accounted for.', 'applied', 'planned', null),
  (57 , 6, 'Merge two already ordered streams', 'Combine two sorted sequences into one sorted result while preserving all required items.', 'Two-stream merge; pointer movement; stability', 'A complete merge trace with correct ordering and multiplicity.', 'applied', 'planned', null),
  (58 , 6, 'Merge overlapping intervals', 'Sort and combine overlapping ranges while retaining non-overlapping ranges correctly.', 'Interval sorting; overlap; merge boundary', 'A valid interval merge result for touching and overlapping cases.', 'applied', 'planned', null),
