  (64 , 7, 'Traverse a tree depth first', 'Choose preorder, inorder, postorder or a general depth-first visit order to answer a tree question.', 'DFS; traversal order; subtree reasoning', 'A correct traversal sequence and explanation of the chosen order.', 'applied', 'planned', null),
  (65 , 7, 'Explore a tree or graph level by level', 'Use breadth-first reasoning when distance in edges or nearest-level discovery matters.', 'BFS; queue; levels; unweighted distance', 'A breadth-first traversal with correct visitation order.', 'applied', 'planned', null),
  (66 , 7, 'Model a graph from a real relationship problem', 'Translate locations, users, dependencies or connections into vertices and edges with direction and weight where needed.', 'Graph modelling; directed/undirected; weighted/unweighted', 'A graph model that preserves the domain relationships.', 'applied', 'planned', null),
