  (69 , 7, 'Reason about shortest paths', 'Distinguish unweighted shortest path from weighted shortest path and identify when a simple level search is insufficient.', 'Shortest path; distance; weights; nonnegative costs', 'A suitable shortest-path method choice with assumptions stated.', 'advanced', 'planned', null),
  (70 , 7, 'Solve a graph-based scenario', 'Select a graph representation and traversal strategy for a practical connectivity, dependency or routing problem.', 'Graph synthesis; traversal; constraints', 'A complete graph problem plan with a testable result.', 'synthesis', 'planned', null),
