  (75 , 8, 'Compare scanning, sorting and hashing costs', 'Choose a strategy based on the number of queries, update frequency, input properties and memory budget.', 'Scan; sort; hash; query volume', 'A method comparison with preconditions and costs stated.', 'applied', 'planned', null),
  (76 , 8, 'Select structures for scale', 'Re-evaluate a data structure choice when the input grows or the operation mix changes.', 'Scale; workload; update/query ratio', 'A structure choice that remains plausible at the stated scale.', 'applied', 'planned', null),
  (77 , 8, 'Establish a brute-force baseline before optimising', 'Create a simple correct baseline and identify the repeated work an optimisation should remove.', 'Baseline; bottleneck; optimisation target', 'A correct baseline and a specific, justified improvement.', 'applied', 'planned', null),
  (78 , 8, 'Solve under streaming and memory constraints', 'Reason about data that arrives incrementally and cannot all be retained in memory.', 'Streaming; bounded memory; online processing', 'A one-pass or bounded-memory strategy with stated limitations.', 'advanced', 'planned', null),
  (79 , 8, 'Evaluate caching and recomputation', 'Decide when stored results are worth their memory, invalidation and staleness risks.', 'Caching; recomputation; invalidation; freshness', 'A caching decision with correctness and freshness conditions.', 'advanced', 'planned', null),
  (80 , 8, 'Optimise a solution without breaking its contract', 'Improve an approach under explicit time and memory constraints while preserving required behaviour.', 'Optimisation synthesis; correctness; performance', 'A before/after plan with preserved acceptance criteria.', 'synthesis', 'planned', null),
  (81 , 9, 'Turn requirements into test cases', 'Derive tests from normal behaviour, boundaries, constraints and acceptance criteria.', 'Test design; expected result; coverage', 'A small, high-value test set linked to requirements.', 'building', 'planned', null),
  (82 , 9, 'Design boundary and adversarial tests', 'Construct cases that challenge assumptions, expose overflow, duplicates, ordering errors and worst-case patterns.', 'Boundary tests; adversarial cases; counterexamples', 'An adversarial test set with the defect each case targets.', 'applied', 'planned', null),
  (83 , 9, 'Use invariants to argue correctness', 'Explain why a procedure remains correct at each step by identifying a property that must always hold.', 'Loop invariants; proof outline; correctness', 'A coherent correctness argument for a short procedure.', 'applied', 'planned', null),
  (84 , 9, 'Trace a defect to its source', 'Use observed output, intermediate states and a minimal failing case to narrow a defect to its source.', 'Debugging; trace; minimal failing case', 'A defect hypothesis supported by a reproducible trace.', 'applied', 'planned', null),
  (85 , 9, 'Diagnose a wrong algorithm, not just a wrong line', 'Recognise when a solution strategy fails for a class of inputs even if individual statements appear reasonable.', 'Algorithmic defects; counterexamples; strategy mismatch', 'A counterexample and a corrected high-level approach.', 'advanced', 'planned', null),
  (86 , 9, 'Check regressions and unintended side effects', 'Verify that a proposed change fixes the target issue without breaking earlier behaviour or altering unrelated data.', 'Regression; side effects; scope of change', 'A regression checklist with targeted tests.', 'advanced', 'planned', null),
  (87 , 9, 'Handle missing, malformed and inconsistent data', 'Choose safe behaviour for absent fields, invalid formats, duplicate identifiers and contradictory records.', 'Validation; robustness; defensive reasoning', 'A defensive data-handling policy with explicit outcomes.', 'advanced', 'planned', null),
  (88 , 9, 'Review generated code or pseudocode critically', 'Inspect a supplied solution for requirement mismatch, faulty assumptions, hidden complexity and missing tests.', 'Code review; requirement fit; correctness; complexity', 'A review containing specific defects, evidence and recommended changes.', 'advanced', 'planned', null),
  (89 , 9, 'Verify an AI suggestion independently', 'Treat AI output as a proposal, then validate its assumptions, behaviour, edge cases and evidence before accepting it.', 'AI output evaluation; independent testing; steering', 'A keep/change/reject decision backed by tests and reasoning.', 'advanced', 'planned', null),
  (90 , 9, 'Make an engineering judgement under uncertainty', 'Balance correctness, risk, scope, maintainability and time when information is incomplete.', 'Risk; uncertainty; judgement; communication', 'A recommendation with assumptions, trade-offs and a validation plan.', 'synthesis', 'planned', null),
  (91 , 10, 'Solve an event-registration data problem', 'Count distinct participants from noisy form submissions while preserving the source data and stating the output contract.', 'Deduplication; identity; counting; data quality', 'A complete approach and tests for repeated, empty and unique records.', 'applied', 'planned', null),
  (92 , 10, 'Resolve booking and schedule conflicts', 'Detect overlapping reservations and propose a correct conflict policy for time-based records.', 'Intervals; overlap; sorting; boundary policy', 'A schedule-conflict approach with endpoint rules and tests.', 'applied', 'planned', null),
  (93 , 10, 'Reason about inventory changes and audit trails', 'Track stock movements without losing the distinction between current quantity and historical events.', 'State; event logs; aggregation; consistency', 'A stock-update model and an auditable validation approach.', 'applied', 'planned', null),
  (94 , 10, 'Plan deliveries with routes and capacity constraints', 'Model delivery stops and constraints, then reason about feasible routes and priorities.', 'Graphs; capacity; constraints; trade-offs', 'A route-planning strategy with assumptions and feasibility checks.', 'advanced', 'planned', null),
  (95 , 10, 'Design a search and ranking workflow', 'Separate filtering eligibility from ranking relevance and define how ties and missing attributes are handled.', 'Filtering; scoring; ranking; tie-breaking', 'A defensible search-and-ranking pipeline.', 'advanced', 'planned', null),
  (96 , 10, 'Investigate logs, alerts and an incident', 'Use event sequences and symptoms to isolate a likely failure point and prioritise checks.', 'Event ordering; aggregation; root cause; triage', 'An incident investigation plan with evidence and next tests.', 'advanced', 'planned', null),
  (97 , 10, 'Interpret an unfamiliar task and code excerpt', 'Read an unfamiliar code or pseudocode fragment, infer its behaviour and relate it to a practical requirement.', 'Code comprehension; tracing; task alignment', 'A behaviour trace, requirement check and defect hypothesis.', 'advanced', 'planned', null),
  (98 , 10, 'Plan, build and review under changing requirements', 'Organise a solution when requirements evolve, distinguish essential changes from scope creep and revise tests.', 'Plan-build-review; change impact; AI-aware judgement', 'A revised plan with changed assumptions, tests and review notes.', 'synthesis', 'planned', null),
  (99 , 10, 'Timed mixed problem-solving assessment', 'Solve unfamiliar tasks under interview-style time pressure using comprehension, modelling, algorithm choice and verification.', 'Transfer; prioritisation; explanation; time management', 'A timed solution dossier and a gap analysis across competencies.', 'capstone', 'planned', null),
  (100 , 10, 'End-to-end problem-solving capstone', 'Independently interpret, model, choose, express, test, verify and defend a solution to a novel scenario without writing code.', 'Full-cycle reasoning; correctness; efficiency; judgement', 'A complete, evidence-backed solution dossier scored against a common rubric.', 'capstone', 'planned', null)
) as x(module_number,stage_number,title,objective,focus,expected_evidence,learning_tier,content_status,unused)
where c.slug='problem-solving-lab'
on conflict (module_number) do update set stage_number=excluded.stage_number,title=excluded.title,objective=excluded.objective,focus=excluded.focus,expected_evidence=excluded.expected_evidence,learning_tier=excluded.learning_tier,content_status=excluded.content_status,published_at=case when excluded.content_status='published' then coalesce(public.course_modules.published_at,now()) else public.course_modules.published_at end;

-- Module 01 public question text and options (no answer key is exposed).
insert into public.assessment_questions(question_id,module_number,sort_order,title,prompt,options,hints,marks,is_published) values
('m1q01',1,1, 'Identify the requested entity', 'An online bookstore stores order records with customer ID, order ID, order date and product ID. One customer may place several orders on the same day, and one order may contain several products. The manager asks: ‘How many different customers placed at least one order on 12 June?’ Which statement captures the requested task?', '["Count all product lines recorded on 12 June.", "Count the distinct order IDs recorded on 12 June.", "Count the distinct customer IDs linked to orders on 12 June.", "Count the distinct product IDs sold on 12 June."]'::jsonb, '["Ask what real-world thing the manager wants a number for: line items, orders, products or people.", "One customer can appear in several order records, so counting records is not necessarily counting customers.", "The requested result is one count per different customer identity among the orders dated 12 June."]'::jsonb, 2, true),
('m1q02',1,2, 'Separate context from the task', 'A parking authority operates four locations and uses camera-based entry logs. For Lot A, it wants to know how many different vehicles entered between 08:00 and 10:00. Which sentence states the actual task rather than background information or an implementation idea?', '["The authority operates four parking locations.", "Use a dictionary to store vehicle registration numbers.", "Count distinct vehicle registration numbers recorded at Lot A between 08:00 and 10:00.", "Improve the accuracy of the entry cameras."]'::jsonb, '["The actual task should describe the result the authority wants, not merely the environment it works in.", "A data structure is a possible way to implement a solution; it does not define the requested outcome.", "Look for the sentence that names the count, the vehicle identity and the stated location and time window."]'::jsonb, 2, true),
('m1q03',1,3, 'Recognise scope creep', 'A student portal stores login events. The stated request is: ‘Report the number of distinct accounts that logged in at least once on Monday.’ Which proposed deliverable adds work that the request does not ask for?', '["Use Monday as the reporting period.", "Count an account only once even if it logged in several times.", "Return a single numeric count of the qualifying accounts.", "Send a reactivation message to every account that did not log in on Monday."]'::jsonb, '["Separate what is necessary to produce the requested report from what might be a useful follow-up campaign.", "The request is about accounts that did log in, not taking action on accounts that did not.", "Look for the option that creates a new communication workflow instead of producing the requested count."]'::jsonb, 2, true),
('m1q04',1,4, 'Distinguish an entity from its events', 'A museum gate log contains successful entry scans. A visitor may appear in more than one scan record because the gate was slow to respond. The museum asks for the number of different visitors who entered on a given date. What should the requested count represent?', '["The number of scan events recorded that day.", "The number of distinct visitor identities represented in the day’s entry scan records.", "The number of times each gate sensor activated.", "The number of passes printed for the museum."]'::jsonb, '["A scan is an event. A visitor is the real-world entity the museum wants to count.", "One visitor can cause more than one scan event, so an event count can overstate the number of visitors.", "The count must be based on different visitor identities, restricted to the specified date."]'::jsonb, 2, true),
('m1q05',1,5, 'Identify an ambiguity that needs clarification', 'A procurement team asks for a report showing the number of ‘active suppliers’ this quarter. Its records contain supplier IDs, purchase orders, deliveries and invoices, but the request does not define the word ‘active’. What is the best next step before writing the task statement?', '["Assume any supplier with an invoice is active.", "Count every supplier ID appearing anywhere in the records.", "Ask which business condition qualifies a supplier as active, such as an order placed, a delivery completed or another agreed rule.", "Choose the fastest data structure and use that as the definition."]'::jsonb, '["The reporting period is stated, but one important term that determines who belongs in the result is not.", "Different definitions of ‘active’ can produce different counts from the same records.", "Clarify the business meaning of the word before deciding which records qualify."]'::jsonb, 2, true),
('m1q06',1,6, 'Transfer the skill to a new domain', 'A learning platform asks: ‘How many learners completed a course in November?’ Its event log records when a learner opened a lesson, played a video, started a quiz and submitted a quiz. The platform has not defined what ‘completed a course’ means. What should the problem solver do first?', '["Treat opening the final lesson as course completion.", "Treat every quiz submission as course completion.", "Clarify the completion rule, such as whether all required units must be finished or an assessment must be passed.", "Count every event in November and divide by the number of courses."]'::jsonb, '["The date range is clear, but the condition that determines whether a learner belongs in the count is not.", "Opening content, playing a video and submitting a quiz are different activities; none is automatically equivalent to completion.", "Ask the platform owner to state the exact completion criterion before counting learners."]'::jsonb, 2, true)
on conflict (question_id) do update set sort_order=excluded.sort_order,title=excluded.title,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,marks=excluded.marks,is_published=excluded.is_published;

-- Answer keys and option-level explanations live in the non-exposed private schema.
insert into private.assessment_answer_keys(question_id,correct_index,explanation,option_explanations) values
('m1q01', 2, 'The manager asks for the number of different customers, not the number of order records, products or line items. Customer ID is the field that identifies the customer. The task is therefore to count each distinct customer ID represented by at least one order dated 12 June once. Multiple orders or product lines belonging to the same customer must not increase the customer count.', '["This counts product-line records. An order containing several products can contribute several lines, and one customer can place several orders. The result would measure lines, not different customers.", "This counts orders. A customer who places two separate orders would contribute two to this count, even though the manager wants that person counted once.", "This matches the requested entity and time condition: identify customers through customer ID, restrict to orders dated 12 June, and count each customer ID once.", "This counts product identities. A customer may buy several products, and several customers may buy the same product. Product count is not customer count."]'::jsonb),
('m1q02', 2, 'A task statement expresses the required result in terms of the relevant entity and stated conditions. The authority wants a count of different vehicles for Lot A during a specific time window. The number of locations is context, a dictionary is an implementation choice, and camera improvement is a separate project goal.', '["This gives background about the authority. It does not say what result must be produced for Lot A.", "This proposes an implementation technique. A solver should understand the required result before choosing a data structure.", "This states the outcome (count), the entity (distinct vehicles), and the applicable location and time window. It is the task itself.", "This is a possible operational improvement, but the stated request is to count vehicles from the available records."]'::jsonb),
('m1q03', 3, 'The requested deliverable is a count of distinct accounts that logged in on Monday. A reactivation campaign is a separate product or business action. It may be useful, but it is not required to calculate or return the requested count. Adding it without approval is scope creep.', '["This applies the explicit date condition in the request. It is necessary to identify the relevant events.", "This follows the word ‘distinct’: repeated logins by one account must not make that account count several times.", "This expresses the requested output as a count and remains within the stated scope.", "This adds a separate communication action for a different group of accounts. The prompt does not request messages or a reactivation workflow."]'::jsonb),
('m1q04', 1, 'The museum asks how many different visitors entered, so the thing being counted is the visitor, not the scan event, sensor activation or printed pass. The task must count each visitor identity once among the successful entry scan records for the specified date. Repeated scans from the same visitor do not represent additional visitors.', '["This counts events. Because a visitor may scan more than once, the event total can be greater than the number of different visitors.", "This counts the correct real-world entity and avoids treating repeat scans as additional people.", "Sensor activations describe equipment activity, not the number of people who entered.", "Printed passes may include unused passes and do not establish how many different visitors actually entered on the date."]'::jsonb),
('m1q05', 2, '‘Active supplier’ is ambiguous because it could mean a supplier with a purchase order, a completed delivery, an invoice, a payment or another agreed activity. These definitions can produce different results. The solver should ask the stakeholder to define the qualifying condition before writing a precise task statement or choosing a solution.', '["This silently invents a definition. An invoice may not be the agreed evidence of supplier activity, so the assumption could produce the wrong report.", "This counts any supplier mentioned in any record, regardless of whether that record represents the business activity intended by ‘active’.", "This identifies the missing business rule and asks the stakeholder to resolve it. That is the safest way to make the task precise.", "A data structure affects implementation, not the business definition of which suppliers qualify. It cannot resolve the ambiguity."]'::jsonb),
('m1q06', 2, 'The word ‘completed’ is not defined by the event names alone. Opening a lesson, playing a video, starting a quiz and submitting a quiz describe different actions. The platform must define the completion rule—for example, all required units completed, a required assessment passed, or an explicit completion status—before the solver can decide which learners qualify. Choosing one activity as completion without confirmation would introduce an unsupported assumption.', '["The prompt does not say that opening the final lesson is sufficient. This option invents a completion rule.", "Submitting a quiz may not mean the learner passed it or completed the rest of the course. The prompt does not establish this rule.", "This resolves the missing definition instead of guessing. A precise completion condition is needed before the count can be determined.", "This produces a ratio based on activity volume, not the number of learners who completed a course. It also does not address the undefined completion rule."]'::jsonb)
on conflict (question_id) do update set correct_index=excluded.correct_index,explanation=excluded.explanation,option_explanations=excluded.option_explanations;

-- Module 01 written activities; responses are persisted per student in lesson_activity_responses.
insert into public.course_activities(activity_id,module_number,sort_order,title) values
('m1-a1',1,1,'Extract the task'),
('m1-a2',1,2,'Find the missing definition'),
('m1-a3',1,3,'Help-desk report'),
('m1-a4',1,4,'Course completion report')
on conflict (activity_id) do update set module_number=excluded.module_number,sort_order=excluded.sort_order,title=excluded.title;
